class Solution {
    public int removeDuplicates(int[] nums) {
        int[] kept = new int[nums.length];
        int size = 0;
        int runLength = 0;
        int previous = 0;
        for (int index = 0; index < nums.length; index++) {
            if (index == 0 || nums[index] != previous) {
                previous = nums[index];
                runLength = 1;
            } else {
                runLength++;
            }
            if (runLength <= 2) kept[size++] = nums[index];
        }
        System.arraycopy(kept, 0, nums, 0, size);
        return size;
    }
}

